const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Arabian Sea geometry
  const arabianSea = ee.Geometry.Polygon([
    [[55, 10], [75, 10], [75, 25], [55, 25], [55, 10]]
  ]);

  // 2. Define time period
  const startDate = '2023-06-01';
  const endDate = '2023-06-30';

  // 3. Load SST data
  let sstCollection = ee.ImageCollection('NOAA/CDO/OISST/V2_1')
    .filterDate(startDate, endDate)
    .filterBounds(arabianSea);

  const collectionSize = sstCollection.size().getInfo();
  console.log(`SST Images found: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("No SST data available for June 2023 in Arabian Sea.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 4. Get maximum SST across the time period
  const maxSST = sstCollection.select('sst').max();

  // 5. Calculate statistics
  const stats = maxSST.reduceRegion({
    reducer: ee.Reducer.max().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: arabianSea,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const maxTemp = stats.sst_max;
  const pixelCount = stats.sst_count;

  console.log(`Valid pixels: ${pixelCount}`);
  console.log(`Maximum SST: ${maxTemp !== null ? maxTemp.toFixed(2) : 'null'}°C`);

  // 6. Validation and answer
  if (pixelCount === 0 || pixelCount === null) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (maxTemp === null || maxTemp === undefined || isNaN(maxTemp)) {
    console.log("Calculation failed - invalid result.");
    console.log("<answer>C3</answer>");
    return;
  }

  // SST sanity check (should be between -5 and 45°C)
  if (maxTemp < -5 || maxTemp > 45) {
    console.log("Unrealistic SST value detected.");
    console.log("<answer>C3</answer>");
    return;
  }

  // 7. Final answer
  if (maxTemp >= 30.0) {
    console.log("SST reached at least 30°C in Arabian Sea during June 2023.");
    console.log("<answer>A</answer>");
  } else {
    console.log("SST did not reach 30°C in Arabian Sea during June 2023.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
